const X0=-2.6,Y0=0.7,N=40,EV=10;
function rnd(a){a|=0;a=a+0x6D2B79F5|0;let t=Math.imul(a^a>>>15,1|a);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296;}
function noise(inp,seed,k){const s=inp.batchSize==='full'?0:2/Math.sqrt(+inp.batchSize);const u1=rnd(seed*1000+k*2+1)+1e-9,u2=rnd(seed*1000+k*2+2);const r=Math.sqrt(-2*Math.log(u1));return[s*r*Math.cos(6.283185*u2),s*r*Math.sin(6.283185*u2)];}
const L=(x,y)=>0.5*(x*x+4*y*y);
function fresh(saved){return{x:X0,y:Y0,k:0,t:0,trail:[[X0,Y0]],saved:saved||[],st:0};}
export function initialState(){return fresh([]);}
export function reduce({state,event,inputs,seed}){
if(event.type==='parameter')return fresh(state.saved);
if(event.type==='action'){const id=event.id||event.action;if(id==='keep')return fresh(state.trail);return state;}
if(event.type!=='step'||state.st)return state;
const t=state.t+1;if(t<EV)return{...state,t};
const lr=inputs.learningRate,n=noise(inputs,seed,state.k);
const x=state.x-lr*(state.x+n[0]),y=state.y-lr*(4*state.y+n[1]),k=state.k+1;
const st=L(x,y)>4.5?2:(k>=N?1:0);
return{...state,x,y,k,t:0,st,trail:state.trail.concat([[x,y]])};}
function pos(x,y,lift){return[x,Math.min(0.4*L(x,y),3)+lift,y];}
function q(dx,dz){const m=Math.hypot(dx,dz)||1,s=0.7071068;return[dz/m*s,0,-dx/m*s,s];}
function arrow(v,p){const m=Math.hypot(v[0],v[1]);const len=Math.min(1.4,Math.max(0.25,0.35*m));return{position:p,quaternion:q(v[0],v[1]),scale:[1,len,1],visible:true};}
export function evaluate({inputs,seed,state}){
const s=state||fresh([]),nodes={};
const bp=pos(s.x,s.y,0.12);nodes.ballN={position:bp};
const running=s.st===0;
const n=noise(inputs,seed,running?s.k:Math.max(0,s.k-1));
const gx=s.x,gy=4*s.y;
if(running){nodes.aTrue=arrow([-gx,-gy],bp);nodes.aNoisy=arrow([-(gx+n[0]),-(gy+n[1])],bp);}
else{nodes.aTrue={visible:false};nodes.aNoisy={visible:false};}
nodes.statusLbl={visible:!running,text:s.st===2?'Diverged':'40 steps done'};
for(let i=0;i<=N;i++){const a=s.trail[i],b=s.saved[i];nodes['t'+i]=a?{visible:true,position:pos(a[0],a[1],0.03)}:{visible:false};nodes['s'+i]=b?{visible:true,position:pos(b[0],b[1],0.03)}:{visible:false};}
return{nodes,readouts:{loss:L(s.x,s.y),dist:Math.hypot(s.x,s.y),stepN:s.k,noise:Math.hypot(n[0],n[1])}};}
